import {T} from './core.js?v=75';
// Perimeters are measured from rendered triangles, not idealized polygon rings.
export function surfacePerimeter(mesh){const g=mesh.geometry,p=g.attributes.position,ix=g.index,edges=new Map(),point=i=>new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(mesh.matrixWorld),key=v=>v.toArray().map(x=>Math.round(x*100000)).join(',');for(let i=0;i<(ix?.count??p.count);i+=3){const ids=[0,1,2].map(j=>ix?ix.getX(i+j):i+j);for(let j=0;j<3;j++){const a=point(ids[j]),b=point(ids[(j+1)%3]),ka=key(a),kb=key(b);if(ka===kb)continue;const k=ka<kb?ka+'|'+kb:kb+'|'+ka;if(edges.has(k))edges.get(k).count++;else edges.set(k,{a,b,count:1});}}return [...edges.values()].filter(e=>e.count===1&&Math.hypot(e.b.x-e.a.x,e.b.z-e.a.z)>1e-6);}
export function nearestEdge(x,z,edges){let result=null;for(const {a,b}of edges){const dx=b.x-a.x,dz=b.z-a.z,t=Math.max(0,Math.min(1,((x-a.x)*dx+(z-a.z)*dz)/(dx*dx+dz*dz))),distance=Math.hypot(x-a.x-dx*t,z-a.z-dz*t);if(!result||distance<result.distance)result={distance,y:a.y+(b.y-a.y)*t};}return result;}
export function edgeSurface(scene,material,name,edges,bottom,extras={}){const pos=[],uv=[],ix=[];for(const {a,b}of edges){const ay=bottom(a),by=bottom(b);if(Math.abs(a.y-ay)<1e-5&&Math.abs(b.y-by)<1e-5)continue;const n=pos.length/3;pos.push(a.x,a.y,a.z,a.x,ay,a.z,b.x,b.y,b.z,b.x,by,b.z);uv.push(a.x/4,a.z/4,a.x/4,a.z/4,b.x/4,b.z/4,b.x/4,b.z/4);ix.push(n,n+1,n+2,n+2,n+1,n+3);}if(!ix.length)return null;const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ix);g.computeVertexNormals();const ma=material.clone();ma.side=T.DoubleSide;const o=new T.Mesh(g,ma);o.name=name;o.castShadow=false;o.receiveShadow=true;o.userData={surfaceSeamRepair:true,...extras};scene.add(o);return o;}
